// A data directory p2 wrote on Chord v1 (test/fixtures/v1-data) is migrated to per-host stores (`npm run migrate-data`)
// and opens on this p2 with nothing lost: the data report reads the same before and after (either layout), every
// conversation's newest entry shows through `Chat` (scripts/verify-sessions.ts), and subagents, shares, artifacts,
// downloads, uploads, search, environments and port forwards read back through their contracts. The fixture is never
// written: the test works on a copy.
// The fixture (`data/`, `report.json`) was generated by p2 on Chord v1 at aee97d3a9, with the fake provider.

import assert from "node:assert/strict";
import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { BACKGROUND_CONTEXT } from "@p2/app/v1";
import { ArtifactList } from "../../plugins/artifacts/contract.ts";
import { Chat } from "../../plugins/chat/contract.ts";
import { Envs } from "../../plugins/envs/contract.ts";
import { Ports } from "../../plugins/ports/contract.ts";
import { Search } from "../../plugins/search/contract.ts";
import { Sharing } from "../../plugins/sharing/contract.ts";
import { Subagents } from "../../plugins/subagents/contract.ts";
import { type DataReport, dataReport } from "../../scripts/data-report.ts";
import { migrateData } from "../../scripts/migrate-data.ts";
import { verifySessions } from "../../scripts/verify-sessions.ts";
import { startServer } from "../../src/hosts/server.ts";
import { clientHost, holdIn, http, localOwner, until } from "./helpers.ts";

const fixture = new URL("../fixtures/v1-data/", import.meta.url);
const expected = JSON.parse(readFileSync(new URL("report.json", fixture), "utf8")) as DataReport;
const byTitle = (title: string): string => {
	const found = Object.entries(expected.sessions).find(([, session]) => session.title === title);
	assert(found, title);
	return found[0];
};

test("a v1 data directory opens with everything in it", { timeout: 120_000 }, async (t) => {
	const root = mkdtempSync(join(tmpdir(), "p2-v1-data-"));
	t.after(() => rmSync(root, { recursive: true, force: true }));
	const dataDir = join(root, "data");
	cpSync(new URL("data/", fixture), dataDir, { recursive: true });
	assert.deepEqual(dataReport(dataDir), expected);
	// The old layout is refused until it is migrated; a dry run changes nothing.
	await assert.rejects(startServer({ dataDir, port: 0, fake: true, web: false }), /migrate-data/);
	const dry = await migrateData({ dataDir, dryRun: true });
	assert.equal(dry.sessions.migrated.length, 3);
	assert.deepEqual(dry.sessions.failed, []);
	assert.deepEqual(
		readdirSync(join(dataDir, "sessions")).filter((name) => !name.includes(".sqlite")),
		[],
	);
	const migrated = await migrateData({ dataDir, dryRun: false });
	assert.deepEqual(migrated.sessions.failed, []);
	assert.deepEqual(migrated.sessions.migrated, Object.keys(expected.sessions).sort());
	assert.deepEqual({ entries: migrated.entries, files: migrated.files }, { entries: 26, files: 3 });
	assert.deepEqual(readdirSync(join(dataDir, "sessions")).sort(), Object.keys(expected.sessions).sort());
	assert.deepEqual(readdirSync(join(dataDir, "pre-files-backup")).sort(), ["artifacts", "downloads", "sessions"]);
	assert.deepEqual(dataReport(dataDir), expected);
	// Again: nothing left to do.
	const again = await migrateData({ dataDir, dryRun: false });
	assert.deepEqual([again.sessions.migrated, again.sessions.skipped, again.sessions.failed], [[], [], []]);

	const server = await startServer({ dataDir, port: 0, fake: true, web: false });
	try {
		const url = `http://127.0.0.1:${server.port}`;
		assert.deepEqual(await verifySessions(url, expected, dataDir), []);
		const alpha = byTitle("Alpha");
		const beta = byTitle("Beta");
		// A report that differs is told apart.
		const root1 = expected.sessions[alpha]!.conversations["1"]!;
		const off: DataReport = {
			...expected,
			sessions: {
				...expected.sessions,
				[beta]: { ...expected.sessions[beta]!, title: "Renamed" },
				[alpha]: {
					...expected.sessions[alpha]!,
					conversations: {
						...expected.sessions[alpha]!.conversations,
						"1": { ...root1, newest: root1.newest + 1 },
					},
				},
			},
		};
		assert.deepEqual(await verifySessions(url, off, dataDir), [
			`${beta}: title "Renamed" -> "Beta"`,
			`${alpha}/1: newest entry ${root1.newest + 1} -> ${root1.newest}`,
		]);
		const local = await localOwner(server);
		const headers = { Cookie: local.cookie };
		const owner = clientHost(local);
		t.after(() => owner.close(BACKGROUND_CONTEXT));

		const children = await holdIn(owner, Subagents, {}, "reader");
		const worktree = (await until(children.children, (value) => Boolean(value?.[alpha]?.length)))?.[alpha]?.[0];
		assert.equal(worktree?.name, "worktree");
		assert.deepEqual(worktree?.location, { env: null, cwd: "/" });

		const sharing = await holdIn(owner, Sharing, { session: beta }, "owner");
		assert.deepEqual(
			(await until(sharing.links, Boolean))?.map((link) => link.mode),
			["view"],
		);

		const artifacts = await holdIn(owner, ArtifactList, { session: alpha, conversation: 1 }, "reader");
		assert.deepEqual(
			(await until(artifacts.artifacts, (value) => Boolean(value?.length)))?.map((info) => [
				info.name,
				info.version,
			]),
			[["demo", 1]],
		);

		const artifact = await http(
			server.port,
			`/artifact?${new URLSearchParams({ session: alpha, name: "demo", version: "1" })}`,
			{ headers },
		);
		assert.equal(artifact.status, 200);
		const [download] = readdirSync(join(dataDir, "pre-files-backup", "downloads", alpha));
		const sent = await http(server.port, `/download?${new URLSearchParams({ session: alpha, id: download ?? "" })}`, {
			headers,
		});
		assert.equal(sent.status, 200);
		assert.equal(sent.body, "sent by send_file\n");

		// The old upload's id still attaches it: materialized where it was, under the data directory's uploads.
		const [upload] = readdirSync(join(dataDir, "uploads", beta));
		const chat = await holdIn(owner, Chat, { session: beta, conversation: 1 }, "participant");
		await chat.send(
			{ text: "", requestId: "migrated-upload", attachments: [upload!.slice(0, 36)] },
			BACKGROUND_CONTEXT,
		);
		await until(chat.view, (view) =>
			JSON.stringify(view?.entries ?? []).includes(
				JSON.stringify(join(dataDir, "uploads", beta, upload!)).slice(1, -1),
			),
		);
		chat.release();

		const search = await holdIn(owner, Search, {}, "owner");
		const hits = await search.search({ query: "hello beta" }, BACKGROUND_CONTEXT);
		assert.ok(hits.messages.some((hit) => hit.session === beta));

		const envs = await holdIn(owner, Envs, {}, "owner");
		assert.deepEqual(
			(await envs.list(BACKGROUND_CONTEXT)).map((env) => env.name),
			["gpu"],
		);
		const ports = await holdIn(owner, Ports, {}, "owner");
		assert.deepEqual(
			(await until(ports.forwards, Boolean))?.map((forward) => [forward.port, forward.name]),
			[[5173, "web"]],
		);
	} finally {
		await server.close();
	}
	const after = dataReport(dataDir);
	// The upload sent above is a message more in Beta, and nothing else changed.
	assert.deepEqual(
		{ ...after, sessions: { ...after.sessions, [byTitle("Beta")]: expected.sessions[byTitle("Beta")] } },
		expected,
	);
});
